#!/usr/bin/env node
/**
 * generate-family-week-notes.mjs — the bilingual raw material the Family
 * Connections publisher uses to write a weekly note.
 *
 * WHY A GENERATED FILE
 *   The two sources are large and split across the repo: 84 curated bilingual
 *   sidecars in data/family-homework-notes/ and one config.json per lesson
 *   (hundreds of KB each) for vocabulary. A publisher that fetched those in the
 *   browser would pull megabytes to write three sentences. This is the compact
 *   projection — nothing here is authored, every string is copied verbatim from
 *   a curated source, so the note the teacher sees is the Spanish an ESOL
 *   parent has already been reading in the homework.
 *
 * Deterministic by construction: sorted keys, no timestamps. A no-op run must
 * leave the file byte-identical or tools/family-week-notes.test.mjs fails.
 *
 *   node scripts/generate-family-week-notes.mjs [--check]
 */
import { readdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";

const ROOT = path.resolve(import.meta.dirname, "..");
const NOTES_DIR = path.join(ROOT, "data", "family-homework-notes");
const MANIFEST = path.join(ROOT, "data", "curriculum-manifest.json");
const OUT = path.join(ROOT, "data", "family-week-notes.json");
const VOCAB_PER_LESSON = 3;

const clean = (value, max = 320) =>
  String(value ?? "")
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, max);

/** A bilingual pair is only usable when BOTH lanes are real. Half a pair in the
 * Spanish lane is how English ends up in front of a Spanish-reading parent. */
function pair(en, es, max) {
  const enText = clean(en, max);
  const esText = clean(es, max);
  return enText && esText ? { en: enText, es: esText } : null;
}

/* The first `vocabulary` entry is usually the lesson's topic header rather than
 * a word ("Understand Ratios", "Ratio Tables"), and a note that says "we are
 * working with understand ratios" reads like a machine wrote it. Detect it by
 * overlap with the lesson title instead of trusting position alone — some
 * lessons really do lead with a term ("doer of math"). */
const significantWords = (text) =>
  String(text ?? "")
    .toLowerCase()
    .split(/[^a-z0-9]+/)
    .filter((word) => word.length >= 3)
    .map((word) => word.replace(/s$/, ""));

function isTopicHeader(term, title) {
  const words = significantWords(term);
  if (!words.length) return false;
  const titleWords = new Set(significantWords(title));
  return words.every((word) => titleWords.has(word));
}

async function lessonVocabulary(lessonId, title) {
  const configPath = path.join(ROOT, "lessons", lessonId, "config.json");
  let config;
  try {
    config = JSON.parse(await readFile(configPath, "utf8"));
  } catch {
    return [];
  }
  const seen = new Set();
  const terms = [];
  const entries = config.vocabulary ?? [];
  for (const [index, entry] of entries.entries()) {
    const term = pair(entry?.term, entry?.termEs, 60);
    if (!term) continue;
    if (index === 0 && isTopicHeader(term.en, title)) continue;
    /* "Ratio Tables" and "Ratio table" are the same word to a parent — a note
     * that lists both reads like a bug. */
    const key = term.en.toLowerCase().replace(/s$/, "");
    if (seen.has(key)) continue;
    seen.add(key);
    terms.push(term);
    if (terms.length === VOCAB_PER_LESSON) break;
  }
  return terms;
}

export async function buildFamilyWeekNotes() {
  const files = (await readdir(NOTES_DIR)).filter((name) => name.endsWith(".json")).sort();
  const manifest = JSON.parse(await readFile(MANIFEST, "utf8"));
  const titles = new Map((manifest.lessons ?? []).map((lesson) => [lesson.id, lesson.title]));
  const lessons = {};
  for (const file of files) {
    const lessonId = file.replace(/\.json$/, "");
    const notes = JSON.parse(await readFile(path.join(NOTES_DIR, file), "utf8"));
    const bigIdea = pair(notes?.bigIdea?.en, notes?.bigIdea?.es, 320);
    const learning = pair(notes?.learningTonight?.en, notes?.learningTonight?.es, 320);
    const vocabulary = await lessonVocabulary(lessonId, titles.get(lessonId) ?? "");
    if (!bigIdea && !learning && !vocabulary.length) continue;
    const entry = {};
    if (bigIdea) entry.bigIdea = bigIdea;
    if (learning) entry.learning = learning;
    if (vocabulary.length) entry.vocabulary = vocabulary;
    lessons[lessonId] = entry;
  }
  return {
    note: "GENERATED by scripts/generate-family-week-notes.mjs — do not hand-edit. Sources: data/family-homework-notes/<id>.json (curated bilingual parent notes) and lessons/<id>/config.json (curated bilingual vocabulary).",
    schemaVersion: 1,
    lessons,
  };
}

export function serialize(bank) {
  return `${JSON.stringify(bank, null, 2)}\n`;
}

if (import.meta.filename === process.argv[1]) {
  const bank = await buildFamilyWeekNotes();
  const text = serialize(bank);
  if (process.argv.includes("--check")) {
    const current = await readFile(OUT, "utf8").catch(() => "");
    if (current !== text) {
      console.error(
        "data/family-week-notes.json is stale — run npm run generate:family-week-notes",
      );
      process.exit(1);
    }
    console.log(`family-week-notes: fresh (${Object.keys(bank.lessons).length} lessons)`);
  } else {
    await writeFile(OUT, text);
    console.log(
      `family-week-notes: wrote ${Object.keys(bank.lessons).length} lessons to data/family-week-notes.json`,
    );
  }
}
